// Додзё КАЙТАКА — зал клуба. Первый уровень и хаб между главами.
//
// Собран по фотографиям настоящего зала: синие пазловые маты, светлые
// стены с фактурой, белый потолок с круглыми светильниками, две тёмные
// деревянные колонны посреди зала, полотно с эмблемой на фронтальной
// стене и роспись с солнцем и горами на противоположной.
//
// Это ОПИСАНИЕ, а не код: arena.js читает его и расставляет всё сам.
// Двигать предметы, добавлять новые и менять свет можно прямо здесь.
//
// Оси: X — вдоль зала, Y — высота, Z — глубина.

import { C } from "../../scene/palette.js";
import { BELTS } from "../belts.js";

// Стороны обязаны быть чётными: маты кладутся метр на метр от середины
// зала, и при нечётной стороне ряд поехал бы на полметра.
const L = 16, D = 14, H = 2.9;
const BACK = -D / 2, FRONT = D / 2;
const LEFT = -L / 2, RIGHT = L / 2;

export const DOJO = {
  id: "dojo",
  name: "ДОДЗЁ",
  jp: "道場",
  // {приёмы} подставляется из набора текущего режима — он свой у зала
  // и у поединка, и подсказка должна меняться вместе с кнопками.
  tip: "Стрелки — идти, держи дольше — побежит · {приёмы} · T — режим · V — вид",

  length: L,
  depth: D,
  wallHeight: H,

  // Соревновательная площадка посреди зала: восемь на восемь метров
  // с красной окантовкой в один мат — как на настоящих татами.
  competition: { size: 8, border: 1 },

  // Режим движения (fight/moves.js). Здесь отработка на макиварах — это
  // кихон, а не поединок: боец ходит свободно и поворачивается к снаряду.
  mode: "training",

  // Свет как в зале: тёплые лампы сверху и сильная синяя подсветка снизу
  // от матов. Именно она красит потолок и стены в голубой на фотографиях,
  // и без неё зал не узнать.
  light: {
    bg: 0x0a1020,
    sky: 0xfdf4e6,
    ground: C.mat,
    ambient: 1.45,
    sun: 0xfff0d6,
    sunPower: 1.5,
    sunPos: [-4, 6, 5],
    fogNear: 22,
    fogFar: 46
  },

  props: [
    // Полотно с эмблемой — фронтальная стена, место чести.
    { type: "banner", x: 0, y: 1.62, z: BACK + 0.06, w: 4.6, h: 1.6, logo: true },

    // Роспись во всю противоположную стену: солнце, горы, бамбук,
    // пагода и силуэт бойца в маваси-гери.
    { type: "mural", x: 0, y: 1.45, z: FRONT - 0.06, w: 9.5, h: 2.3, ry: Math.PI },

    // Две колонны посреди зала — главная примета КАЙТАКА.
    { type: "column", x: -2.6, y: 0, z: BACK + 1.5, h: H },
    { type: "column", x:  2.6, y: 0, z: BACK + 1.5, h: H },

    // Двери по краям фронтальной стены.
    { type: "door", x: -6.4, y: 0, z: BACK + 0.05 },
    { type: "door", x: -5.2, y: 0, z: BACK + 0.05 },
    { type: "door", x:  6.2, y: 0, z: BACK + 0.05 },

    // Окна высоко под потолком вдоль левой стены, под ними радиаторы.
    ...[-5.5, -2, 1.5, 5].flatMap(z => ([
      { type: "window",   x: LEFT + 0.06, y: 2.12, z, ry:  Math.PI / 2 },
      { type: "radiator", x: LEFT + 0.14, y: 0.30, z, ry:  Math.PI / 2 }
    ])),

    // Стойка с поясами у правой стены.
    { type: "beltRack", x: RIGHT - 0.12, y: 1.75, z: -1.5, ry: -Math.PI / 2,
      belts: BELTS.filter(b => !b.stripe).map(b => b.color) },

    // Снаряды для задания. Вынесены на середину зала, между колоннами
    // и маршрутом сэнсэя: у настоящих их и выносят на занятие, а потом
    // убирают. Обойти можно с любой стороны.
    { type: "makiwara", x: -5.4, y: 0, z: -1.4, target: 0 },
    { type: "makiwara", x: -1.8, y: 0, z: -1.4, target: 1 },
    { type: "makiwara", x:  1.8, y: 0, z: -1.4, target: 2 },
    { type: "makiwara", x:  5.4, y: 0, z: -1.4, target: 3 },

    // Мешки у правой стены — обстановка.
    { type: "bag", x: RIGHT - 1.0, y: 0, z: 3.2 },
    { type: "bag", x: RIGHT - 1.0, y: 0, z: 4.6 }
  ],

  // ЗАДАНИЕ ПЕРВОГО УРОВНЯ.
  //
  // Всё, что можно подкрутить, лежит здесь: число снарядов, ударов на
  // каждый, время и слова сэнсэя. Логику этапа править не нужно.
  task: {
    kind: "makiwara",
    hits: 20,
    seconds: 60,
    reach: 0.7,       // вдвое меньше прежнего: с полутора метров удар
                      // засчитывался с явно чужого расстояния

    // Сэнсэй объясняет отсюда, потом обходит зал по этому прямоугольнику.
    // Обход идёт левыми поворотами — так устроен его клип.
    sensei: { x: 0, z: BACK + 2.4 },
    // Маршрут обходит колонны и снаряды: колонны стоят на z = −5,
    // снаряды на z = −1.4, сэнсэй ходит по краю между ними и стенами.
    patrol: { x0: LEFT + 1.6, x1: RIGHT - 1.6, z0: BACK + 3.6, z1: FRONT - 1.4 },

    brief: [
      "ОСУ, {имя}!",
      "Сегодня — макивара. Четыре снаряда.",
      "Двадцать ударов на каждый. На всё — одна минута.",
      "Бей от бедра. Начали!"
    ],
    win:  "ОСУ! Хорошая работа.",
    lose: "Время вышло. Ещё раз — с начала."
  },

  targets: [
    { x: -5.4, z: -1.4 },
    { x: -1.8, z: -1.4 },
    { x:  1.8, z: -1.4 },
    { x:  5.4, z: -1.4 }
  ]
};
